  "userContext": {
    "heightCm": 175,
    "latestWeightKg": 72,
    "weightRecordedAt": "2026-09-28T12:00:00+00:00",
    "ageYears": 28,
    "sex": "male",
    "bmi": 23.5
  },
  "targetPeriod": {
    "periodStart": "2026-09-28",
